import {p} from './foodwise-helpers.mjs';
export const foodwiseFoods=[
{id:7,
title:p('The Threefold Plant','A planta tríplice'),
goal:p('Explain the root–leaf–fruit correspondence and use it as a way of reading plant form.','Explique a correspondência raiz–folha–fruto e use-a para ler a forma vegetal.'),
theory:[p('Cook compares the plant’s root, leafy middle and flowering or fruiting region with the human nerve-sense, rhythmic and metabolic-limb systems. The root takes up minerals in the cooler earth; the leafy middle opens rhythmically to air and light; flowering and fruiting express warmth and ripening in her account.','Cook compara raiz, região folhosa e região floral ou frutífera aos sistemas neurossensorial, rítmico e metabólico-motor. A raiz absorve minerais na terra mais fria; as folhas se abrem ritmicamente ao ar e à luz; flores e frutos expressam calor e amadurecimento em seu relato.'),p('The correspondence is inverted: root relates to head, leaf and stem to heart and lungs, blossom and fruit to metabolism. She uses similarities of activity to propose effects of eating plant parts. The observation of a shape and the proposed therapeutic effect are different steps in the argument.','A correspondência é invertida: raiz relaciona-se à cabeça, folha e caule ao coração e pulmões, flor e fruto ao metabolismo. Cook usa semelhanças de atividade para propor efeitos alimentares. Observar uma forma e propor um efeito terapêutico são etapas diferentes do argumento.'),p('The chapter surveys vegetable families and fruits, from carrots and brassicas to gourds and the rose family. These examples offer a vocabulary of growth, colour, aroma and edible parts. Later Cook turns the threefold picture into a menu-planning aid. It encourages variety but does not calculate nutritional completeness.','O capítulo percorre famílias de vegetais e frutas, das cenouras e brássicas às cucurbitáceas e rosáceas. Oferece vocabulário de crescimento, cor, aroma e partes comestíveis. Depois, Cook usa a imagem tríplice para planejar cardápios. Ela favorece variedade, mas não calcula completude nutricional.')],
quoteTranslation:p(null,'A planta manifesta uma natureza tríplice correspondente à natureza tríplice do corpo humano'),
close:p('“Corresponding” asserts a relationship. Ask whether each supporting detail is botanical description, analogy or a claim about human health.','“Correspondente” afirma uma relação. Pergunte se cada detalhe é descrição botânica, analogia ou afirmação sobre saúde.'),
example:p('A meal contains carrot, cabbage and apple.','Uma refeição contém cenoura, repolho e maçã.'),
explanation:p('It represents a root, leaves and fruit. This illustrates Cook’s pattern; it does not show that the meal contains enough energy, protein or every essential nutrient.','Representa raiz, folhas e fruto. Ilustra o padrão de Cook; não mostra que a refeição fornece energia, proteína ou todos os nutrientes essenciais em quantidade suficiente.'),
takeaways:[p('Learn the three plant regions.','Aprenda as três regiões vegetais.'),p('Explain the inverted correspondence.','Explique a correspondência invertida.'),p('A symbolic pattern is not a nutritional calculation.','Um padrão simbólico não é cálculo nutricional.')],
activity:p('Draw a carrot plant and label root, leaves and blossom. Beside it draw Cook’s human correspondences. Add an observation supporting each analogy and one question the analogy cannot answer.','Desenhe uma cenoura e marque raiz, folhas e flores. Ao lado, desenhe as correspondências humanas. Acrescente uma observação para cada analogia e uma pergunta que ela não responde.'),
checks:[[p('Which plant region corresponds to the head?','Qual região corresponde à cabeça?'),p('The root, in Cook’s inverted plant model.','A raiz, no modelo invertido de Cook.')],[p('What mediates the two poles?','O que faz a mediação entre os polos?'),p('The leafy middle corresponds to the rhythmic heart-lung region.','A região folhosa corresponde à região rítmica cardiopulmonar.')],[p('Does colour prove a healing effect?','A cor prova um efeito curativo?'),p('No. A visible quality can prompt investigation without establishing a treatment claim.','Não. Uma qualidade visível pode estimular investigação sem comprovar tratamento.')]],
context:p('The specific organ and colour correspondences are anthroposophical interpretations. They should not be used to diagnose deficiencies or prescribe foods for an illness.','As correspondências específicas de órgãos e cores são interpretações antroposóficas. Não devem diagnosticar deficiências nem prescrever alimentos para doenças.')},
{id:8,references:['diabetes','infants','diet'],
title:p('Carbohydrates and Sweeteners','Carboidratos e adoçantes'),
goal:p('Follow Cook’s distinction between transforming whole foods and consuming concentrated sweetness.','Acompanhe a distinção entre transformar alimentos integrais e consumir doçura concentrada.'),
theory:[p('Cook begins with plants building carbohydrates through light and warmth, then reverses the direction to human digestion. She values the work of breaking down complex food, connecting it spiritually with individual activity. Starch and sweetness become parts of a process, rather than simply ingredients on a label.','Cook começa com a formação vegetal de carboidratos pela luz e calor e inverte a direção para a digestão humana. Valoriza o trabalho de decompor alimentos complexos, ligando-o espiritualmente à atividade individual. Amido e doçura tornam-se partes de um processo, além de ingredientes no rótulo.'),p('Her historical sequence moves from honey in the flower realm to cane sugar in the stem and beet sugar in the root. This carries the threefold plant picture into food history. She also describes refining, molasses, maple syrup and other sweeteners, asking what is retained or removed during production.','Sua sequência histórica vai do mel no domínio floral ao açúcar de cana no caule e ao de beterraba na raiz. A imagem tríplice entra na história alimentar. Ela também descreve refino, melaço, xarope de bordo e outros adoçantes, perguntando o que a produção retém ou remove.'),p('Sweetness has an emotional as well as sensory role in the chapter. Cook’s concern is proportion and quality, not the elimination of all pleasure. But the chapter’s medical claims, especially its statement about stopping diabetes medication, must be separated from this discussion of food experience.','A doçura tem papel emocional e sensorial. Cook se preocupa com proporção e qualidade, sem eliminar o prazer. Entretanto, as afirmações médicas, sobretudo a de interromper medicamentos para diabetes, precisam ser separadas da reflexão sobre experiência alimentar.')],
quoteTranslation:p(null,'Entretanto, as pessoas estão obtendo cada vez mais sua nutrição de carboidratos na forma de açúcar refinado, particularmente nos países ocidentais.'),
close:p('The contrast concerns the form in which carbohydrate is consumed. It does not equate every carbohydrate food with refined sugar.','O contraste trata da forma de consumo do carboidrato. Não equipara todos os alimentos com carboidratos ao açúcar refinado.'),
example:p('A student replaces all added sugar with honey and calls the recipe sugar-free.','Um estudante troca todo açúcar adicionado por mel e chama a receita de sem açúcar.'),
explanation:p('The source and flavour changed, but honey still contributes free sugars. Cook’s interest in production history cannot erase composition.','Origem e sabor mudaram, mas o mel continua fornecendo açúcares livres. O interesse de Cook na história produtiva não elimina a composição.'),
takeaways:[p('Distinguish starch-rich foods and concentrated sweeteners.','Distinga alimentos ricos em amido e adoçantes concentrados.'),p('The flower–stem–root sequence is interpretive.','A sequência flor–caule–raiz é interpretativa.'),p('Food discussion must not become medication advice.','A discussão alimentar não deve virar orientação medicamentosa.')],
activity:p('Compare two sweetener labels and describe origin, processing, taste and sugar content. Explain what changed and what did not; do not alter medication or feeding plans.','Compare dois rótulos de adoçantes: origem, processamento, sabor e açúcares. Explique o que mudou e o que permaneceu, sem alterar medicamentos ou planos alimentares.'),
checks:[[p('Why does Cook discuss plant regions?','Por que Cook discute regiões vegetais?'),p('She links the source of sweetness with her broader spiritual history of nutrition.','Relaciona a origem da doçura à história espiritual da nutrição.')],[p('Can diet replace insulin for type 1 diabetes?','A dieta substitui insulina no diabetes tipo 1?'),p('No. NIDDK explains the need for insulin; treatment changes require the treating clinician.','Não. O NIDDK explica a necessidade de insulina; mudanças exigem o profissional responsável.')],[p('Is honey appropriate for an infant under one year?','Mel é adequado antes de um ano?'),p('No. CDC advises against honey before 12 months because of infant botulism risk.','Não. O CDC orienta não oferecer mel antes de 12 meses pelo risco de botulismo infantil.')]],
context:p('Do not follow the book’s claim that most people with diabetes can stop insulin after dietary change. Honey is unsuitable below 12 months. WHO includes honey and syrups among free sugars.','Não siga a afirmação de que a maioria das pessoas com diabetes pode suspender insulina após mudar a dieta. Mel é inadequado antes de 12 meses. A OMS inclui mel e xaropes entre açúcares livres.')},
{id:9,references:['celiac'],
title:p('Bread and Bread Making','Pão e panificação'),
goal:p('Explain why time, fermentation and sharing are central to Cook’s account of bread.','Explique por que tempo, fermentação e partilha são centrais no relato sobre o pão.'),
theory:[p('Cook tells bread’s biography from grain pastes to raised loaves, specialized bakers and mechanized production. Bread connects field, mill, kitchen and table. Its religious and social meanings accompany the technical story; sharing bread makes companionship a tangible act.','Cook conta a biografia do pão, das pastas de grãos aos pães fermentados, padeiros especializados e produção mecanizada. O pão conecta campo, moinho, cozinha e mesa. Sentidos religiosos e sociais acompanham a técnica; partilhá-lo torna concreta a convivência.'),p('Her main criticism of industrial shortcuts is the loss of time between stages. Ripening, resting flour, fermentation, kneading and cooling become opportunities for transformation. She describes her Majorcan bread-making experience to show how skill and attention coordinate flour, water, warmth and timing.','Sua principal crítica aos atalhos industriais é a perda do tempo entre etapas. Amadurecimento, descanso da farinha, fermentação, sova e resfriamento tornam-se oportunidades de transformação. A experiência em Maiorca mostra como habilidade e atenção coordenam farinha, água, calor e tempo.'),p('The chapter distinguishes yeast, sourdough and a honey-salt method interpreted through polarities. It ends with bread and wine as spiritual symbols. Keep the observable fermentation process, the baker’s judgments and the symbolic interpretation visible as different layers of the lesson.','O capítulo distingue fermento, massa madre e um método de mel e sal interpretado por polaridades. Termina com pão e vinho como símbolos espirituais. Diferencie processo fermentativo observável, avaliações do padeiro e interpretação simbólica.')],
quoteTranslation:p(null,'O tempo é um dos elementos mais importantes no percurso do campo à mesa, simplesmente porque esse percurso é de transformação.'),
close:p('Time becomes an ingredient in a process. The statement invites you to ask what each pause allows to happen, rather than assuming that longer is always better.','O tempo torna-se ingrediente do processo. A frase convida a perguntar o que cada pausa permite, sem presumir que mais tempo é sempre melhor.'),
example:p('A recipe includes a rest that an impatient baker wants to omit.','Uma receita inclui um descanso que um padeiro impaciente quer eliminar.'),
explanation:p('Identify its function first: hydration, fermentation or cooling. Then consider the likely effect on dough or loaf. A meaningful reason is more useful than treating a pause as a ritual alone.','Identifique primeiro sua função: hidratação, fermentação ou resfriamento. Considere o efeito sobre massa ou pão. Uma razão clara vale mais do que tratar a pausa apenas como ritual.'),
takeaways:[p('Bread unites a chain of transformations.','O pão reúne uma cadeia de transformações.'),p('Pauses have functions.','Pausas têm funções.'),p('Craft and symbolism are related but distinct.','Ofício e simbolismo são relacionados, mas distintos.')],
activity:p('Annotate a familiar bread recipe with what happens during each active step and each wait. Add one paragraph on the meaning of sharing bread in Cook’s chapter.','Anote numa receita conhecida o que acontece em cada etapa ativa e em cada espera. Acrescente um parágrafo sobre a partilha do pão no capítulo.'),
checks:[[p('What is lost when time is omitted?','O que se perde ao eliminar tempo?'),p('Potential stages of transformation; the exact effect depends on which stage is shortened.','Possíveis etapas de transformação; o efeito depende da etapa encurtada.')],[p('Does honey-salt language replace fermentation?','A linguagem de mel e sal substitui a fermentação?'),p('No. It interprets a bread-making method; conditions for fermentation still matter.','Não. Interpreta um método; as condições de fermentação continuam importantes.')],[p('Is wheat sourdough gluten-free?','Pão de trigo com fermentação natural é sem glúten?'),p('No. Fermenting ordinary wheat bread does not make it suitable for coeliac disease.','Não. Fermentar pão comum de trigo não o torna adequado à doença celíaca.')]],
context:p('Use a reliable recipe for actual baking. Cook’s praise of traditional fermentation must not be read as assurance that wheat, spelt, rye or barley bread is safe for coeliac disease.','Use uma receita confiável para assar. O elogio à fermentação tradicional não garante que pães de trigo, espelta, centeio ou cevada sejam seguros na doença celíaca.')},
{id:10,references:['tobacco'],
title:p('The Nightshade Family','A família das solanáceas'),
goal:p('Distinguish botanical kinship, preparation history and Cook’s claims about consciousness.','Distinga parentesco botânico, história do preparo e afirmações sobre consciência.'),
theory:[p('Cook brings potatoes, tomatoes, aubergines, peppers and tobacco into one botanical discussion, alongside toxic members of the same family. She reads growth forms, odours and nitrogen through an anthroposophical lens. Botanical kinship invites comparison; it does not give every member the same effects or hazards.','Cook reúne batata, tomate, berinjela, pimentões e tabaco numa discussão botânica, junto a membros tóxicos da família. Lê formas, odores e nitrogênio pela antroposofia. Parentesco convida à comparação; não dá a todos os membros os mesmos efeitos ou riscos.'),p('The potato’s journey includes Andean preservation, European adoption and dependence on a vulnerable staple. Preparation and agricultural diversity matter in this story. Cook then introduces Steiner’s and Hauschka’s claims connecting potatoes with abstract thinking and memory. Those claims are a separate interpretive layer.','A trajetória da batata inclui conservação andina, adoção europeia e dependência de um alimento vulnerável. Preparo e diversidade agrícola importam. Cook introduz depois afirmações de Steiner e Hauschka ligando batatas ao pensamento abstrato e à memória. Elas constituem outra camada interpretativa.'),p('The tomato and tobacco sections extend the theme of strong plant qualities and human habits. Cook sometimes makes sweeping claims but also cautions against blanket statements. Reading the chapter well means preserving that tension, without treating a plant’s supposed character as a diagnosis of its eater.','As seções sobre tomate e tabaco ampliam o tema das qualidades vegetais e dos hábitos. Cook faz afirmações amplas, mas também adverte contra generalizações. Ler bem exige preservar essa tensão, sem transformar o caráter atribuído à planta em diagnóstico de quem a consome.')],
quoteTranslation:p(null,'portanto, devemos ter cuidado com afirmações generalizantes.'),
close:p('This is a clause from Cook’s qualification about individual variation. Read it beside the strong claims preceding it; it does not silently cancel them.','A oração vem da ressalva de Cook sobre diferenças individuais. Leia-a junto às afirmações fortes anteriores; ela não as cancela silenciosamente.'),
example:p('Someone infers that tomatoes must be avoided because tobacco belongs to the same family.','Alguém conclui que deve evitar tomates porque o tabaco pertence à mesma família.'),
explanation:p('That inference skips species, compounds, preparation and exposure. Family membership alone cannot establish the conclusion.','A inferência ignora espécie, substâncias, preparo e exposição. O parentesco sozinho não estabelece a conclusão.'),
takeaways:[p('Related plants can have different effects.','Plantas aparentadas podem ter efeitos diferentes.'),p('Preparation and cultivation have histories.','Preparo e cultivo têm histórias.'),p('Do not diagnose character from diet.','Não diagnostique caráter pela alimentação.')],
activity:p('Create separate rows for potato, tomato and tobacco. Record a botanical feature, a cultural example and an attributed claim. Identify a conclusion that does not follow from botanical kinship.','Crie linhas para batata, tomate e tabaco. Registre característica botânica, exemplo cultural e afirmação atribuída. Identifique uma conclusão que não decorre do parentesco.'),
checks:[[p('What does kinship establish?','O que o parentesco estabelece?'),p('A botanical relationship, not identical nutritional or toxic effects.','Uma relação botânica, não efeitos nutricionais ou tóxicos idênticos.')],[p('What does the potato history teach?','O que ensina a história da batata?'),p('A staple is embedded in preservation, trade and agricultural dependence.','Um alimento básico está inserido em conservação, comércio e dependência agrícola.')],[p('Can the tomato passage guide cancer care?','O trecho sobre tomate orienta cuidados de câncer?'),p('No. Its spiritual analogy is not a clinical basis for excluding tomatoes or changing treatment.','Não. A analogia espiritual não é base clínica para excluir tomates ou mudar tratamentos.')]],
context:p('Do not apply the chapter’s claims about tomatoes and carcinoma or potatoes and children’s memory as medical advice. Tobacco’s serious health harms are independently documented by WHO.','Não aplique as afirmações sobre tomate e carcinoma ou batata e memória infantil como orientação médica. Os graves danos do tabaco são documentados independentemente pela OMS.')},
{id:11,references:['soy'],
title:p('Legumes','Leguminosas'),
goal:p('Connect legumes’ agricultural role with preparation, proportion and the debate over soya.','Relacione o papel agrícola das leguminosas ao preparo, à proporção e ao debate sobre soja.'),
theory:[p('Cook reads the legume family through its relationship with nitrogen, including root bacteria and its place in crop rotations. She adds a spiritual interpretation of nitrogen as a carrier of sentient life. The agricultural relationship and the proposed consciousness relationship should be explained separately.','Cook lê as leguminosas por sua relação com o nitrogênio, incluindo bactérias nas raízes e rotação de culturas. Acrescenta a interpretação espiritual do nitrogênio como portador de sensibilidade. A relação agrícola e a relação proposta com a consciência precisam de explicações separadas.'),p('Soya becomes a case study in scale and processing: bean, fermented food, oil, flour, industrial ingredient and animal feed are different uses. Cook worries about monoculture and commercial expansion, while contrasting traditional preparation with newer applications. Asking which product and which production system prevents the discussion becoming too vague.','A soja exemplifica escala e processamento: grão, fermentado, óleo, farinha, ingrediente industrial e ração são usos diferentes. Cook se preocupa com monocultura e expansão comercial e contrasta preparo tradicional e aplicações recentes. Identificar produto e sistema produtivo evita uma discussão vaga.'),p('The chapter returns to everyday foods—lentils, chickpeas, beans—and to the cook’s handling of them. Cook values their place in satisfying meals while emphasizing proportion and individual experience. Her caution about excess does not amount to a rejection of the whole family.','O capítulo retorna a lentilhas, grão-de-bico, feijões e seu preparo. Cook valoriza seu lugar em refeições satisfatórias, destacando proporção e experiência individual. Sua cautela com excessos não equivale à rejeição da família inteira.')],
quoteTranslation:p(null,'Precisamos escolher, e moderação em todas as coisas é meu lema!'),
close:p('Read this after Cook’s positive examples of soups and casseroles. It qualifies her criticism; it is not a quantitative nutrition rule.','Leia após os exemplos positivos de sopas e ensopados. A frase qualifica a crítica; não é regra nutricional quantitativa.'),
example:p('A discussion uses “soya” to mean both tofu in a meal and animal feed grown in a large monoculture.','Uma discussão usa “soja” para tofu numa refeição e ração produzida em monocultura extensa.'),
explanation:p('Separate the product, processing, eater and farming context. An objection to one use does not automatically establish an objection to every use.','Separe produto, processamento, consumidor e contexto agrícola. Uma objeção a um uso não estabelece automaticamente objeção a todos.'),
takeaways:[p('Legumes connect soil and food questions.','Leguminosas conectam solo e alimentação.'),p('Specify which soya product is under discussion.','Especifique o produto de soja discutido.'),p('Cook combines criticism with culinary appreciation.','Cook combina crítica e apreciação culinária.')],
activity:p('Map three uses of soya from the chapter. For each, name a farming question, a processing question and a nutritional question. Use a familiar cooked legume dish as a contrasting example.','Mapeie três usos de soja no capítulo. Para cada um, formule perguntas agrícolas, de processamento e nutricionais. Compare com um prato conhecido de leguminosas cozidas.'),
checks:[[p('What connects legumes and soil fertility?','O que conecta leguminosas e fertilidade?'),p('The chapter discusses nitrogen-fixing bacteria and rotations.','O capítulo discute bactérias fixadoras de nitrogênio e rotações.')],[p('Does Cook exclude all legumes?','Cook exclui todas as leguminosas?'),p('No. She describes using them in soups, casseroles and seasonal dishes.','Não. Descreve seu uso em sopas, ensopados e pratos sazonais.')],[p('How should the infant-formula comparison be read?','Como ler a comparação sobre fórmula infantil?'),p('As a claim requiring clinical evidence, not as a reason to change an infant’s feeding from this book.','Como afirmação que exige evidência clínica, não como motivo para mudar a alimentação de um bebê a partir do livro.')]],
context:p('NCCIH distinguishes soy foods from supplements and discusses uncertainties and allergies. The book’s comparison of soy formula with contraceptive pills is not a dosing equivalence or feeding instruction.','O NCCIH distingue alimentos de soja e suplementos e discute incertezas e alergias. A comparação do livro entre fórmula de soja e anticoncepcionais não é equivalência de dose nem instrução alimentar.')},
{id:12,references:['milk','infants'],
title:p('Milk and Dairy Products','Leite e laticínios'),
goal:p('Distinguish Cook’s mother-and-rhythm symbolism from dairy processing and food safety.','Distinga o simbolismo materno e rítmico de Cook do processamento e da segurança do leite.'),
theory:[p('Milk continues the book’s history of nourishment, from herding cultures to infant feeding and modern dairy products. Cook links it with motherhood, the Moon, rhythm and connection to humanity. Her description of milk as plant-like comes from Steiner’s spiritual account, not a botanical classification.','O leite continua a história da alimentação, das culturas pastoris à nutrição infantil e aos laticínios modernos. Cook o relaciona à maternidade, Lua, ritmo e conexão humana. A descrição como semelhante à planta vem de Steiner, não de classificação botânica.'),p('The practical discussion differentiates animal milks, cream, butter, yoghurt and cheese. Fermentation and processing alter what reaches the eater. Cook asks about the animal’s life, feeding and treatment, joining the agricultural question of Chapter 2 to the product on the table.','A discussão prática distingue leites animais, creme, manteiga, iogurte e queijo. Fermentação e processamento modificam o produto. Cook pergunta pela vida, alimentação e tratamento do animal, ligando a questão agrícola do Capítulo 2 ao alimento na mesa.'),p('Her preference for minimally processed milk coexists with recognition that some people do better without certain dairy foods. The proposed kitchen spoilage experiment aims to develop observation, but smell, appearance and mould patterns cannot certify microbiological safety or nutritional superiority.','A preferência por leite pouco processado convive com o reconhecimento de que algumas pessoas se adaptam melhor sem certos laticínios. O experimento de deterioração proposto busca desenvolver observação, mas cheiro, aparência e padrões de mofo não certificam segurança microbiológica nem superioridade nutricional.')],
quoteTranslation:p(null,'Eu não tentaria negar que algumas pessoas se sentem melhor sem certos laticínios em sua alimentação'),
close:p('The words “some” and “certain” limit the claim. Cook then refers to her daughter; that family example does not establish a universal rule.','“Algumas” e “certos” limitam a afirmação. Cook menciona depois a filha; o exemplo familiar não estabelece regra universal.'),
example:p('A learner calls a milk sample safer because it smells pleasant.','Um estudante considera uma amostra mais segura por ter cheiro agradável.'),
explanation:p('Sensory description and pathogen detection are different tasks. For this course, compare labelled products and processing information rather than growing unknown microbes.','Descrição sensorial e detecção de patógenos são tarefas diferentes. Compare rótulos e processamento, em vez de cultivar microrganismos desconhecidos.'),
takeaways:[p('Milk carries several meanings in the book.','O leite tem vários sentidos no livro.'),p('Processing and individual tolerance matter.','Processamento e tolerância individual importam.'),p('Sensory quality does not establish safety.','Qualidade sensorial não estabelece segurança.')],
activity:p('Compare the labels of pasteurized milk and a yoghurt. Record ingredients, processing, storage instructions and intended use. Add a separate paragraph explaining Cook’s symbolic view of milk.','Compare rótulos de leite pasteurizado e iogurte. Registre ingredientes, processamento, conservação e uso. Explique separadamente a visão simbólica de Cook.'),
checks:[[p('Does plant-like mean milk is a plant food?','Semelhante à planta significa alimento vegetal?'),p('No. It is a spiritual characterization in the chapter.','Não. É uma caracterização espiritual do capítulo.')],[p('What does fermentation change?','O que a fermentação modifica?'),p('It transforms milk into a product such as yoghurt with different properties; it does not make all dairy products interchangeable.','Transforma leite em produto como iogurte, com propriedades diferentes; não torna todos os laticínios intercambiáveis.')],[p('Does an organic source guarantee raw-milk safety?','Origem orgânica garante segurança do leite cru?'),p('No. CDC explains that raw milk can contain harmful germs and that pasteurization improves safety.','Não. O CDC explica que leite cru pode conter germes perigosos e que a pasteurização melhora a segurança.')]],
context:p('Use pasteurized dairy products. Do not reproduce the month-long warm-milk experiment as a tasting activity. Ordinary animal milk and homemade mixtures are not substitutes for appropriate infant feeding.','Use laticínios pasteurizados. Não reproduza o experimento de leite morno durante um mês como degustação. Leites animais comuns e misturas caseiras não substituem alimentação infantil apropriada.')},
{id:13,references:['diet'],
title:p('Fats and Oils','Gorduras e óleos'),
goal:p('Connect the physical behaviour of fats with their culinary roles and Cook’s warmth imagery.','Relacione o comportamento físico das gorduras à culinária e às imagens de calor de Cook.'),
theory:[p('Cook introduces fats through warmth, insulation, energy storage and the boundaries of living cells. She distinguishes oils and more solid fats and describes emulsions. These physical properties provide the starting point for her wider image of fat as both protection and mediation.','Cook introduz gorduras por calor, isolamento, reserva energética e limites celulares. Distingue óleos e gorduras mais sólidas e descreve emulsões. Essas propriedades iniciam sua imagem mais ampla da gordura como proteção e mediação.'),p('Her plant account follows ripening into oil, connecting flavour and aroma with concentrated sunlight. Olive oil receives a cultural biography: cultivation, food, light, ritual and Mediterranean identity. An ingredient’s place in a culture can be studied alongside its composition without making the two identical.','No relato vegetal, o amadurecimento produz óleo, ligando sabor e aroma à luz solar concentrada. O azeite recebe uma biografia cultural: cultivo, alimento, iluminação, ritual e identidade mediterrânea. O lugar cultural de um ingrediente pode ser estudado junto à composição sem igualá-los.'),p('The chapter criticizes refining and hydrogenation and contrasts different oils. Some recommendations reflect its publication period. A student should retain the question about processing while checking current product composition rather than assuming all modern spreads or all animal fats fit a single description.','O capítulo critica refino e hidrogenação e compara óleos. Algumas recomendações refletem a época da publicação. Preserve a pergunta sobre processamento, mas confira a composição atual, sem presumir que todas as pastas vegetais ou gorduras animais sejam iguais.')],
quoteTranslation:p(null,'A primeira observação importante é que elas não são solúveis em água, ao contrário dos sais e carboidratos.'),
close:p('The passage highlights a useful contrast with salt dissolving in water. Its broad wording about carbohydrates should not erase differences between sugars, starches and fibre.','O trecho destaca um contraste útil com a dissolução do sal. A formulação ampla sobre carboidratos não deve apagar diferenças entre açúcares, amidos e fibras.'),
example:p('Oil and water separate in a dressing, then disperse briefly when whisked.','Óleo e água se separam num molho e depois se dispersam brevemente ao bater.'),
explanation:p('This makes mixing and emulsion visible. It illustrates culinary behaviour, not a proof of the spiritual role Cook assigns to warmth.','Isso torna visíveis mistura e emulsão. Ilustra comportamento culinário, não prova o papel espiritual atribuído ao calor.'),
takeaways:[p('Physical properties matter in cooking.','Propriedades físicas importam na cozinha.'),p('Cook reads oil through ripening and warmth.','Cook lê o óleo por amadurecimento e calor.'),p('Check current composition when comparing products.','Confira a composição atual ao comparar produtos.')],
activity:p('Read two oil or spread labels. Compare ingredients and types of fat, then write a separate sensory or cultural description inspired by Cook’s olive-oil section.','Leia dois rótulos de óleos ou pastas. Compare ingredientes e tipos de gordura; depois escreva uma descrição sensorial ou cultural inspirada no trecho sobre azeite.'),
checks:[[p('What is an emulsion?','O que é emulsão?'),p('A dispersion of droplets of one liquid within another that does not simply dissolve in it.','Uma dispersão de gotas de um líquido em outro no qual não se dissolve simplesmente.')],[p('Why include olive-oil history?','Por que incluir a história do azeite?'),p('It connects a substance with work, ritual and a way of life.','Conecta uma substância ao trabalho, ritual e modo de vida.')],[p('Does the book’s praise make butter nutritionally equivalent to olive oil?','O elogio torna manteiga e azeite equivalentes nutricionalmente?'),p('No. Their fatty-acid profiles differ; WHO favours unsaturated over saturated fats.','Não. Seus perfis diferem; a OMS favorece gorduras insaturadas em relação às saturadas.')]],
context:p('WHO distinguishes unsaturated, saturated and trans fats. Cook’s qualitative warmth account and historical margarine discussion do not replace this distinction or a current label.','A OMS distingue gorduras insaturadas, saturadas e trans. A descrição qualitativa do calor e a discussão histórica sobre margarina não substituem essa distinção nem um rótulo atual.')},
{id:14,references:['diet'],
title:p('Salt','Sal'),
goal:p('Distinguish table salt, physiological minerals and the alchemical salt-process.','Distinga sal de cozinha, minerais fisiológicos e processo-sal alquímico.'),
theory:[p('Salt’s history includes preservation, exchange, taxation and enduring agreements. Cook uses these examples to show how a small material can organize social relationships. Its familiar culinary role belongs to a much larger story about value and power.','A história do sal inclui conservação, trocas, impostos e acordos duradouros. Cook mostra como um material pequeno organiza relações sociais. Seu papel culinário integra uma história maior de valor e poder.'),p('Crystallization and dissolution become images of form and movement. In the alchemical vocabulary, salt-process refers broadly to hardening or precipitation, rather than only the sodium chloride on a table. Cook connects this imagery to the nervous system and consciousness.','Cristalização e dissolução tornam-se imagens de forma e movimento. No vocabulário alquímico, processo-sal designa amplamente endurecimento ou precipitação, além do cloreto de sódio à mesa. Cook relaciona essas imagens ao sistema nervoso e à consciência.'),p('The chapter also discusses sodium and potassium and the cook’s use of a small quantity to bring out flavour. It is essential to keep these material roles separate from claims that mineral deposition produces intelligence. Spiritual symbolism supplies no safe dose and no measure of a person’s capacities.','O capítulo discute sódio, potássio e pequenas quantidades para realçar sabores. É essencial separar esses papéis materiais das afirmações de que depósitos minerais produzem inteligência. O simbolismo não fornece dose segura nem medida das capacidades humanas.')],
quoteTranslation:p(null,'Alquimistas e cozinheiros, portanto, familiarizam-se com a atividade dos sais e suas qualidades misteriosas.'),
close:p('“Activity” directs attention to what salt does in a process. The shared attention does not make alchemy and nutritional physiology equivalent.','“Atividade” dirige a atenção ao que o sal faz. Essa atenção compartilhada não torna alquimia e fisiologia nutricional equivalentes.'),
example:p('A student confuses adding more salt with strengthening the book’s salt-process.','Um estudante confunde adicionar mais sal com fortalecer o processo-sal do livro.'),
explanation:p('The word changes meaning between a seasoning and a broad formative principle. The conclusion is therefore unsupported.','A palavra muda de sentido entre tempero e princípio formativo amplo. A conclusão, portanto, não se sustenta.'),
takeaways:[p('Salt has economic and cultural histories.','O sal tem histórias econômica e cultural.'),p('A salt-process is not a spoonful of salt.','Processo-sal não é uma colher de sal.'),p('Necessity does not imply that more is better.','Necessidade não significa que mais é melhor.')],
activity:p('Find three uses of the word salt in the chapter. Label each as substance, physiological discussion or alchemical image. Compare the sodium information on two food labels.','Encontre três usos de sal no capítulo. Classifique-os como substância, discussão fisiológica ou imagem alquímica. Compare o sódio em dois rótulos.'),
checks:[[p('Why did governments control salt?','Por que governos controlavam o sal?'),p('Its widespread necessity made production and taxation politically valuable.','Sua necessidade generalizada tornava produção e tributação politicamente valiosas.')],[p('Does sea salt escape sodium limits?','Sal marinho fica fora dos limites de sódio?'),p('No. Its source does not remove its sodium content.','Não. Sua origem não elimina o sódio.')],[p('Can salt imagery assess intelligence?','Imagens do sal avaliam inteligência?'),p('No. The spiritual interpretation does not establish that clinical claim.','Não. A interpretação espiritual não estabelece essa afirmação clínica.')]],
context:p('WHO recommends limiting salt intake; a necessary mineral is not a reason to increase salt. The chapter’s claims linking pineal deposits to intellectual disability should not be repeated as medical explanations.','A OMS recomenda limitar sal; um mineral necessário não justifica aumentar seu consumo. As afirmações que ligam depósitos pineais à deficiência intelectual não devem ser repetidas como explicações médicas.')},
{id:15,references:['supplements','ph'],
title:p('Minerals and Dietary Supplements','Minerais e suplementos alimentares'),
goal:p('Follow the soil-to-food argument while separating it from blanket claims about supplements and blood pH.','Acompanhe o argumento solo–alimento, distinguindo-o de generalizações sobre suplementos e pH sanguíneo.'),
theory:[p('Cook asks whether reliance on supplements reflects a damaged relationship with soil. She explains soil texture, humus, organisms, weathering and plant–fungus partnerships. The central practical insight is relational: a mineral’s availability depends on a living context, not simply its presence somewhere in the ground.','Cook pergunta se a dependência de suplementos reflete uma relação danificada com o solo. Explica textura, húmus, organismos, intemperismo e parcerias entre plantas e fungos. A ideia prática é relacional: disponibilidade mineral depende do contexto vivo, além da presença no terreno.'),p('The chapter then moves from plant nutrition to minerals acting within human processes, and from there to silica and lime as formative polarities. These transitions connect farming to Cook’s spiritual account of human organization. They also require care: a statement about soil cannot by itself determine how a specific supplement works.','O capítulo passa da nutrição vegetal aos minerais nos processos humanos e à sílica e ao calcário como polaridades formativas. As transições conectam agricultura e organização humana espiritual. Exigem cuidado: uma afirmação sobre solo não determina sozinha o funcionamento de um suplemento.'),p('The ending proposes acid–alkaline food balancing. Distinguish the taste of a food, its proposed classification and the tightly regulated pH of blood. Cook’s concern for good husbandry can be studied without accepting that ordinary meal combinations directly set blood pH or make supplements inherently unusable.','O final propõe equilíbrio alimentar ácido-alcalino. Distinga sabor, classificação proposta e pH sanguíneo rigorosamente regulado. A preocupação com o cultivo pode ser estudada sem aceitar que refeições comuns determinem diretamente o pH sanguíneo ou que suplementos sejam inerentemente inutilizáveis.')],
quoteTranslation:p(null,'O bom manejo conservará e reporá nutrientes vegetais por meio de compostagem adequada e rotação de culturas.'),
close:p('The verbs join conservation with replenishment. The quoted claim concerns husbandry; it does not say that clinical deficiencies never require supplementation.','Os verbos unem conservação e reposição. A afirmação trata de manejo; não diz que deficiências clínicas nunca exigem suplementação.'),
example:p('Someone argues that because compost is valuable, a prescribed mineral supplement must be ineffective.','Alguém argumenta que, como composto é valioso, um suplemento mineral prescrito deve ser ineficaz.'),
explanation:p('The conclusion changes subject from soil management to treatment. It needs evidence about the person, nutrient, dose and formulation.','A conclusão muda de manejo do solo para tratamento. Precisa de evidências sobre pessoa, nutriente, dose e formulação.'),
takeaways:[p('Soil fertility involves living relationships.','A fertilidade envolve relações vivas.'),p('Do not infer supplement efficacy from a soil analogy.','Não deduza eficácia de suplementos de uma analogia com solo.'),p('Food acidity and blood pH are different questions.','Acidez alimentar e pH sanguíneo são questões diferentes.')],
activity:p('Draw soil → plant → meal → person. At each arrow list what must happen for nutrients to become available. Mark where Cook changes from ecological explanation to spiritual analogy.','Desenhe solo → planta → refeição → pessoa. Em cada seta, liste condições de disponibilidade. Marque onde Cook passa de ecologia para analogia espiritual.'),
checks:[[p('What does the fungus receive in the chapter’s partnership?','O que recebe o fungo na parceria descrita?'),p('Sugars from the plant, while helping extend access to soil resources.','Açúcares da planta, enquanto ajuda a ampliar acesso aos recursos do solo.')],[p('Are all supplements unnecessary?','Todos os suplementos são desnecessários?'),p('No. NIH describes useful indications as well as risks; need and dose are specific questions.','Não. O NIH descreve indicações úteis e riscos; necessidade e dose são questões específicas.')],[p('What regulates acid–base balance?','O que regula o equilíbrio ácido-base?'),p('The lungs and kidneys have central roles; a food’s sour taste does not directly determine blood pH.','Pulmões e rins têm papéis centrais; o sabor azedo não determina diretamente o pH sanguíneo.')]],
context:p('NIH ODS explains that supplements may help meet specific needs but can also cause harm. MedlinePlus describes lung and kidney regulation of acid–base balance. Do not change prescribed supplements from this chapter.','O NIH ODS explica que suplementos podem atender necessidades específicas e também causar danos. O MedlinePlus descreve a regulação ácido-base por pulmões e rins. Não mude suplementos prescritos a partir deste capítulo.')},
{id:16,
title:p('Herbs and Spices','Ervas e especiarias'),
goal:p('Read seasoning as an art of proportion, plant identity and sensory attention.','Leia o tempero como arte de proporção, identidade vegetal e atenção sensorial.'),
theory:[p('Herbs and spices connect trade, ritual, medicine and cooking. Cook recalls her first encounter with fresh coriander to show how an aroma can anchor a vivid memory. Seasoning affects the whole experience of a dish, not merely its intensity.','Ervas e especiarias conectam comércio, ritual, medicina e cozinha. Cook lembra seu primeiro encontro com coentro fresco para mostrar como um aroma fixa uma memória. Temperar afeta a experiência inteira do prato, além de sua intensidade.'),p('Her catalogue pays attention to the plant part being used: leaf, seed, bark, flower or rhizome. Basil, rosemary, coriander, cinnamon, ginger and saffron each enter cooking differently. Historical herbal descriptions and planetary associations accompany culinary observations and should remain attributed to that tradition.','O catálogo observa a parte usada: folha, semente, casca, flor ou rizoma. Manjericão, alecrim, coentro, canela, gengibre e açafrão entram na culinária de modos diferentes. Descrições herbais históricas e associações planetárias acompanham observações culinárias e devem permanecer atribuídas à tradição.'),p('The musical analogy offers a practical principle: combine flavours so they support the dish rather than compete for attention. Quantity, timing and preparation matter; raw garlic and roasted garlic are not the same sensory experience. Cook’s medicinal claims require a different standard of evidence from her flavour suggestions.','A analogia musical oferece um princípio: combinar sabores que apoiem o prato, sem disputarem toda a atenção. Quantidade, momento e preparo importam; alho cru e assado não produzem a mesma experiência. Afirmações medicinais exigem outra evidência que sugestões de sabor.')],
quoteTranslation:p(null,'Muitas vezes o segredo de um chef está na combinação sutil de quantidades muito pequenas de ervas e especiarias, individualmente quase irreconhecíveis quando bem feita.'),
close:p('The effect belongs to the combination. “Very tiny amounts” and “if ... done well” make proportion and judgment essential.','O efeito pertence à combinação. “Quantidades muito pequenas” e a condição de ser bem feita tornam proporção e julgamento essenciais.'),
example:p('The same vegetable soup is imagined with parsley or with cumin and coriander.','Imagine a mesma sopa de legumes com salsa ou com cominho e coentro.'),
explanation:p('The base remains, while the aromatic emphasis changes. Explain the intended relationship of flavours rather than declaring one combination universally superior.','A base permanece, enquanto o destaque aromático muda. Explique a relação pretendida entre sabores, sem declarar uma combinação universalmente superior.'),
takeaways:[p('Know which plant part supplies the flavour.','Saiba qual parte fornece o sabor.'),p('Proportion and timing shape the result.','Proporção e momento moldam o resultado.'),p('Culinary use does not prove medicinal efficacy.','Uso culinário não comprova eficácia medicinal.')],
activity:p('Choose three familiar culinary seasonings. Note plant part, aroma, a pairing from the chapter and the point at which you would add it to a dish. Do not use unidentified wild plants.','Escolha três temperos culinários conhecidos. Anote parte vegetal, aroma, combinação do capítulo e momento de adição. Não use plantas silvestres não identificadas.'),
checks:[[p('Why compare herbs with musical notes?','Por que comparar ervas a notas musicais?'),p('The quality depends on their relationship and balance within a whole.','A qualidade depende das relações e do equilíbrio no conjunto.')],[p('Are fresh leaves and dried seeds interchangeable?','Folhas frescas e sementes secas são intercambiáveis?'),p('Not automatically; plant part and preparation change flavour and strength.','Não automaticamente; parte e preparo modificam sabor e intensidade.')],[p('Does a traditional remedy become a prescription here?','Um remédio tradicional vira prescrição aqui?'),p('No. The lesson studies its cultural place without recommending treatment.','Não. A lição estuda seu lugar cultural sem recomendar tratamento.')]],
context:p('The activity concerns normal culinary ingredients, not medicinal doses, essential-oil ingestion or remedies for infants. Historic herbal claims remain claims of the source.','A atividade trata de ingredientes culinários comuns, não de doses medicinais, ingestão de óleos essenciais ou remédios para bebês. Afirmações herbais históricas permanecem atribuídas à fonte.')},
{id:17,references:['caffeine'],
title:p('Stimulants: Coffee, Tea and Chocolate','Estimulantes: café, chá e chocolate'),
goal:p('Connect the experience of stimulation with habits, trade and the book’s concern for freedom.','Relacione estímulo, hábitos, comércio e a preocupação do livro com liberdade.'),
theory:[p('Cook follows coffeehouses, tea drinking and cocoa from cultural encounters into everyday habits. These beverages provide occasions for conversation and pleasure, while their production links consumers with distant land and labour. Sugar enters the story because it makes bitter drinks more palatable.','Cook acompanha cafés, chá e cacau de encontros culturais a hábitos cotidianos. As bebidas criam ocasiões de conversa e prazer, enquanto a produção liga consumidores a terras e trabalho distantes. O açúcar entra por tornar bebidas amargas mais agradáveis.'),p('She distinguishes stimulation from nourishment and asks what happens when a substance lets people override tiredness. Steiner’s descriptions of coffee and tea add different relations between the etheric and physical bodies. Explain those as his proposed spiritual account, alongside the ordinary question about habits and effects.','Ela distingue estímulo e nutrição e pergunta o que ocorre quando uma substância permite ignorar o cansaço. Descrições de Steiner acrescentam relações entre corpos etérico e físico. Explique-as como sua proposta espiritual, junto à questão comum dos hábitos e efeitos.'),p('The chapter turns from personal enjoyment to dependence and the costs of luxury crops. Its useful synthesis is to examine both the drinker’s relationship to a product and the conditions of production. Historical trade figures and legal descriptions should not be reused as current information.','O capítulo passa do prazer à dependência e aos custos das culturas de luxo. A síntese útil examina a relação de quem bebe com o produto e as condições de produção. Números comerciais e descrições legais históricas não devem ser usados como informações atuais.')],
quoteTranslation:p(null,'O único problema era que essas bebidas muitas vezes eram amargas e rústicas e precisavam de açúcar para se tornarem mais agradáveis'),
close:p('This clause links taste to another commodity. Continue reading the sentence in the book: Cook explicitly connects the change to the sugar trade.','A oração liga paladar a outra mercadoria. Continue a frase no livro: Cook conecta explicitamente a mudança ao comércio açucareiro.'),
example:p('A student drinks coffee to enjoy a break, then begins using it to conceal repeated sleep loss.','Um estudante toma café por prazer e depois passa a usá-lo para disfarçar noites repetidamente mal dormidas.'),
explanation:p('The same product has acquired a different function. Describing that shift is more precise than calling every use either freedom or dependence.','O mesmo produto ganhou outra função. Descrever a mudança é mais preciso do que chamar todo uso de liberdade ou dependência.'),
takeaways:[p('Study taste, habit and production together.','Estude paladar, hábito e produção juntos.'),p('Stimulation can mask tiredness.','O estímulo pode mascarar cansaço.'),p('Spiritual descriptions and caffeine evidence are distinct.','Descrições espirituais e evidência sobre cafeína são distintas.')],
activity:p('Make a product biography of coffee, tea or cocoa: plant, processing, labour, added ingredients and place in a daily routine. Use existing observations; no consumption experiment is needed.','Faça uma biografia de café, chá ou cacau: planta, processamento, trabalho, ingredientes adicionados e lugar na rotina. Use observações existentes; não é necessário experimentar consumo.'),
checks:[[p('Why discuss sugar here?','Por que discutir açúcar aqui?'),p('Taste preferences connect stimulant consumption to the history of another crop and trade.','Preferências de sabor conectam estimulantes à história de outra cultura e comércio.')],[p('What can alertness conceal?','O que a sensação de alerta pode esconder?'),p('Fatigue or inadequate rest; feeling stimulated is not the same as being rested.','Cansaço ou descanso insuficiente; estímulo não equivale a descanso.')],[p('Are all people equally sensitive to caffeine?','Todos têm a mesma sensibilidade à cafeína?'),p('No. Sensitivity varies; the chapter’s portraits are not individual assessments.','Não. A sensibilidade varia; os retratos do capítulo não são avaliações individuais.')]],
context:p('FDA describes individual variation in caffeine sensitivity and possible effects on sleep and anxiety. These effects do not establish the book’s etheric-body explanations.','A FDA descreve variação na sensibilidade à cafeína e possíveis efeitos no sono e ansiedade. Esses efeitos não comprovam as explicações sobre corpo etérico.')},
{id:18,references:['water'],
title:p('Water','Água'),
goal:p('Separate water’s ecological role from the chapter’s claims about dynamized water.','Separe o papel ecológico da água das afirmações sobre água dinamizada.'),
theory:[p('This short chapter brings water into the foreground as the medium of living processes. Cook joins bodily fluids to rivers, springs, food and the treatment of landscapes. The ecological question is direct: how do people alter the water systems on which they depend?','Este capítulo breve destaca a água como meio dos processos vivos. Cook conecta fluidos corporais a rios, nascentes, alimentos e paisagens. A pergunta ecológica é direta: como as pessoas alteram os sistemas hídricos dos quais dependem?'),p('Through Alan Hall, Theodor Schwenk and Gerhard Schmidt, the chapter presents water as more than a neutral container. It describes structured or dynamized water and associates it with etheric activity and food quality. These proposed meanings should not be silently treated as established benefits of a drinking-water product.','Por Alan Hall, Theodor Schwenk e Gerhard Schmidt, a água aparece como mais do que recipiente neutro. O capítulo descreve água estruturada ou dinamizada, associando-a à atividade etérica e à qualidade alimentar. Não trate esses sentidos como benefícios comprovados de um produto para beber.'),p('Distinguish water within biological systems, environmental care and potable-water safety. These subjects overlap, but a statement about one does not settle the others. A spring may have cultural and aesthetic value while still needing appropriate assessment before its water is consumed.','Distinga água em sistemas biológicos, cuidado ambiental e segurança para beber. São assuntos relacionados, mas uma afirmação sobre um não resolve os outros. Uma nascente pode ter valor cultural e estético e ainda exigir avaliação antes do consumo.')],
quoteTranslation:p(null,'Todas essas práticas mostram falta de compreensão da natureza intrínseca da água e do quanto tudo na natureza depende dela.'),
close:p('“These practices” refers to damming, straightening riverbanks and dumping waste in the preceding lines. Keep the environmental referent visible.','“Essas práticas” remete a represamento, retificação de margens e descarte de resíduos nas linhas anteriores. Preserve essa referência ambiental.'),
example:p('A bottle advertises water as more alive because it came from a moving stream.','Uma garrafa anuncia água mais viva porque veio de um riacho.'),
explanation:p('The description says something about the story being sold. It does not demonstrate microbiological safety or an additional nutritional benefit.','A descrição mostra a narrativa comercial. Não demonstra segurança microbiológica nem benefício nutricional adicional.'),
takeaways:[p('Water connects bodies and landscapes.','Água conecta corpos e paisagens.'),p('Identify the speaker in quoted claims.','Identifique quem fala nas citações.'),p('A vitality claim is not a potability test.','Vitalidade alegada não é teste de potabilidade.')],
activity:p('Trace the water used in an imagined meal: irrigation, washing, cooking and drinking. For each stage, state an environmental question and a safety question.','Acompanhe a água de uma refeição imaginada: irrigação, lavagem, preparo e bebida. Em cada etapa, formule uma pergunta ambiental e outra de segurança.'),
checks:[[p('What makes water central to the book?','Por que a água é central?'),p('It links living processes, food and the condition of the earth.','Liga processos vivos, alimento e condições da terra.')],[p('Who supplies the opening quotations?','Quem fornece as citações iniciais?'),p('Alan Hall and Theodor Schwenk, as quoted in the book; they are not Cook’s own opening statements.','Alan Hall e Theodor Schwenk, citados no livro; não são declarações próprias de Cook.')],[p('Does clear stream water prove safety?','Água transparente de riacho prova segurança?'),p('No. Appearance does not identify all harmful microorganisms.','Não. A aparência não identifica todos os microrganismos perigosos.')]],
context:p('Use safe drinking water. CDC explains that even clear natural water can contain germs. The chapter does not establish that dynamized or bottled water is safer than a properly treated supply.','Use água potável segura. O CDC explica que mesmo água natural transparente pode conter germes. O capítulo não comprova que água dinamizada ou engarrafada seja mais segura do que uma fonte adequadamente tratada.')}
];
